ALTER TABLE public.news_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY news_categories_select_active ON public.news_categories FOR SELECT TO public USING (is_active=true);
CREATE POLICY news_categories_select_settings_edit ON public.news_categories FOR SELECT TO authenticated USING ((auth.role()='authenticated' AND EXISTS (SELECT 1 FROM public.admin_profiles p JOIN public.admin_user_roles ur ON ur.user_id=p.id JOIN public.admin_roles r ON r.id=ur.role_id LEFT JOIN public.admin_role_permissions rp ON rp.role_id=r.id LEFT JOIN public.admin_permissions perm ON perm.id=rp.permission_id WHERE p.is_active=true AND (p.id=auth.uid() OR lower(p.email)=lower(auth.jwt()->>'email')) AND (r.key='superadmin' OR perm.key='settings.edit'))));
CREATE POLICY news_categories_insert_settings_edit ON public.news_categories FOR INSERT TO authenticated WITH CHECK ((auth.role()='authenticated' AND EXISTS (SELECT 1 FROM public.admin_profiles p JOIN public.admin_user_roles ur ON ur.user_id=p.id JOIN public.admin_roles r ON r.id=ur.role_id LEFT JOIN public.admin_role_permissions rp ON rp.role_id=r.id LEFT JOIN public.admin_permissions perm ON perm.id=rp.permission_id WHERE p.is_active=true AND (p.id=auth.uid() OR lower(p.email)=lower(auth.jwt()->>'email')) AND (r.key='superadmin' OR perm.key='settings.edit'))));
